import requests

base_url = "http://127.0.0.1:43205/v1"
api_key = "arc-proxy"

headers = {
    "Authorization": f"Bearer {api_key}",
    "Content-Type": "application/json"
}

# Try different chat/completion formats
test_data = [
    # Format 1: Chat completion
    {
        "role": "user",
        "content": "Show me examples for task-73499f5a"
    },
    # Format 2: With function call for demos
    {
        "role": "user",
        "content": "Show me input-output examples",
        "request": {"action": "request_demos", "task_id": "task-73499f5a"}
    }
]

for i, data in enumerate(test_data):
    data = {
        "model": "gpt-4o",
        "messages": [data]
    }
    try:
        resp = requests.post(base_url + "/chat/completions", headers=headers, json=data, timeout=10)
        print(f"Format {i+1} - Status: {resp.status_code}")
        if resp.status_code == 200:
            print(f"Success: {resp.json()[:200]}")
        else:
            print(f"Response: {resp.json()[:300]}")
    except Exception as e:
        print(f"Format {i+1} Error: {e}")

import requests
import json

base_url = "http://127.0.0.1:43205/v1"
api_key = "arc-proxy"

headers = {
    "Authorization": f"Bearer {api_key}",
    "Content-Type": "application/json"
}

# Proper chat completion
data = {
    "model": "gpt-4o",
    "messages": [
        {"role": "user", "content": "Show me examples for task-73499f5a"}
    ]
}
try:
    resp = requests.post(base_url + "/chat/completions", headers=headers, json=data, timeout=10)
    print(f"Status: {resp.status_code}")
    result = resp.json()
    if "choices" in result and len(result["choices"]) > 0:
        content = result["choices"][0].get("message", {}).get("content", "")
        print(f"Response content:\n{content}")
    else:
        print(f"Full response: {json.dumps(result, indent=2)[:1000]}")
except Exception as e:
    print(f"Error: {e}")

